RETRY_LIMIT = 5
BACKOFF_BASE = 2
DEFAULT_SERVER_HOST = '127.0.0.1'
DEFAULT_SERVER_PORT = 8080
TARGET_DIRECTORY = './target'
PERSISTENCE_SCRIPT = './target/persistence_script.bat'


def setup_logging():
