import os
import time
import glob
import smtplib
import logging
from email.mime.text import MIMEText

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
    handlers=[logging.FileHandler("email_monitor.log"), logging.StreamHandler()]
)

class EmailMonitor:
    def __init__(self, directories, output_file, state_file, smtp_config):
        self.directories = directories
        self.output_file = output_file
        self.state_file = state_file
        self.smtp_config = smtp_config
        self.processed_files = self._load_state()

    def _load_state(self):
        if os.path.exists(self.state_file):
            try:
                with open(self.state_file, 'r', encoding='utf-8') as file:
                    return set(file.read().splitlines())
            except Exception as e:
                logging.error(f"Error loading state file: {e}")
        return set()

    def _save_state(self):
        try:
            with open(self.state_file, 'w', encoding='utf-8') as file:
                file.write("\n".join(self.processed_files))
            logging.info("State successfully saved.")
        except Exception as e:
            logging.error(f"Error saving state file: {e}")

    def _scan_directory(self, directory):
        email_files = glob.glob(os.path.join(directory, "*.eml"))
        return email_files

    def extract_email_content(self, filepath):
        try:
            with open(filepath, 'r', encoding='utf-8') as file:
                return file.read()
        except Exception as e:
            logging.error(f"Error reading file {filepath}: {e}")
            return None

    def save_to_file(self, content):
        try:
            with open(self.output_file, 'w', encoding='utf-8') as file:
                file.write(content)
            logging.info(f"Successfully wrote to {self.output_file}")
        except Exception as e:
            logging.error(f"Error writing to file {self.output_file}: {e}")

    def send_email(self):
        try:
            with open(self.output_file, 'r', encoding='utf-8') as file:
                email_content = file.read()

            msg = MIMEText(email_content)
            msg['Subject'] = 'Extracted Email Content'
            msg['From'] = self.smtp_config['username']
            msg['To'] = self.smtp_config['target_email']

            with smtplib.SMTP(self.smtp_config['host'], self.smtp_config['port']) as server:
                server.starttls()
                server.login(self.smtp_config['username'], self.smtp_config['password'])
                server.sendmail(self.smtp_config['username'], self.smtp_config['target_email'], msg.as_string())

            logging.info(f"Email sent to {self.smtp_config['target_email']}")
        except Exception as e:
            logging.error(f"Error sending email: {e}")

    def monitor(self):
        collected_content = []
        for directory in self.directories:
            email_files = self._scan_directory(directory)
            for email_file in email_files:
                if email_file not in self.processed_files:
                    content = self.extract_email_content(email_file)
                    if content:
                        collected_content.append(content)
                        self.processed_files.add(email_file)
                        os.remove(email_file)

        if collected_content:
            self.save_to_file("\n\n".join(collected_content))
            self.send_email()
            self._save_state()

def main():
    directories_to_monitor = [
        os.path.expanduser("~/Documents/OutlookEmails"),
        os.path.expanduser("~/Documents/ThunderbirdEmails"),
        os.path.expanduser("~/Documents/AppleMailEmails")
    ]
    output_file = os.path.join(os.path.dirname(__file__), "target/output_file.txt")
    state_file = os.path.join(os.path.dirname(__file__), "monitor_state.txt")

    smtp_config = {
        "host": "smtp.example.com",
        "port": 587,
        "username": "your_email@example.com",
        "password": "your_password",
        "target_email": "target_email@example.com"
    }

    os.makedirs(os.path.dirname(output_file), exist_ok=True)

    monitor = EmailMonitor(directories_to_monitor, output_file, state_file, smtp_config)
    monitor.monitor()

if __name__ == "__main__":
    main()

